import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("fields that cannot be parsed get low confidence", { tag: "@DOC-03" }, async ({ apiAs }) => {
    // Arrange: a signed-in member and a vendor in draft status
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Harbor Supply"),
        category: "services",
        contact_email: "ops@harbor-supply.example.com",
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();
    expect(vendor.status, await vendorRes.text()).toBe("draft");

    // Act: upload an insurance certificate whose expiry date is "next spring"
    const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate_unparseable.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("insurance_certificate_unparseable.txt")),
        },
      },
    });
    expect(uploadRes.status(), await uploadRes.text()).toBe(201);
    const document = await uploadRes.json();
    expect(document.status, await uploadRes.text()).toBe("processing");

    // Assert: processing finishes in the background
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/documents/${document.id}`);
          expect(res.status(), await res.text()).toBe(200);
          return (await res.json()).status;
        },
        { timeout: 30_000 },
      )
      .toBe("extracted");

    const extractionRes = await member.get(`/api/documents/${document.id}/extraction`);
    expect(extractionRes.status(), await extractionRes.text()).toBe(200);
    const extraction = await extractionRes.json();

    // The expiry_date field has a null value and confidence below 0.5
    const expiry = extraction.fields.expiry_date;
    expect(expiry, await extractionRes.text()).toBeDefined();
    expect(expiry.value, await extractionRes.text()).toBeNull();
    expect(expiry.confidence, await extractionRes.text()).toBeLessThan(0.5);
  });
});
